#!/bin/bash
# Task 076 -- meshsim v1.2 (WORKER4, branch v1.2-meshsim at 9cb675a): phase 6's close. run_tests.sh's quick suite (31 Java
# steps, 8 at a time, the recipes included), then its full-mode extras (CtrlTest/AccountingTest/ReadPortGatherTest/
# EngineTest full, the quick sweep, AgBench, the skew table, S1Bench; 4 at a time). The kit (wip/meshsim with Java 17
# classes and prebuilt images, wip/sw's REGISTERS.md, RECIPES.md, headers and recipes, wip/tools/replayer-opcodes;
# run_quick.sh, run_full.sh) is embedded below, SHA-256 checked; smoke-tested locally (RegDocTest, RecipeTest).
# Commits every log, VERDICT.txt and FULL-VERDICT.txt. Expected 30-50 min, about 24 GB.
set -u
cd "$(dirname "$0")/.."
RES=$PWD/results/076-meshsim-v12-phase6; mkdir -p "$RES"
WANT=3af28738f9113274b66718ec95d8d4eee0467dd0bb5f24d94b6c9a9afce4bfcb
W=/tmp/ms-076; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "$WANT" ] || { echo "kit sha256 mismatch (want $WANT)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
cd "$W/wip/meshsim" || exit 2
echo "start $(date -u) on $(hostname), $(nproc) threads"; java -version 2>&1 | head -1
P=8 ./run_quick.sh "$W/out"; RQ=$?
P=4 ./run_full.sh "$W/out"; RF=$?
echo "run_quick.sh exit $RQ, run_full.sh exit $RF at $(date -u)"
cp "$W"/out/* "$RES/" 2>/dev/null
cat "$W/out/VERDICT.txt" "$W/out/FULL-VERDICT.txt" 2>/dev/null
[ $RQ = 0 ] && [ $RF = 0 ]
